#include <utility>
#include <string>
#include <typeinfo>

int main() {
    // Type deduction is automatic
    auto p1 = std::make_pair(42, "literal"); 

    // Explicit construction required type specification
    std::pair<int, const char*> p2(42, "literal");

    // Demonstrating deduction (int, const char*)
    // std::cout << typeid(p1.first).name() << "\n";

    // Note: make_pair is often used to insert into maps:
    // map.insert(std::make_pair("key", value));

    return 0;
}
